//! Beardifier vs the vanilla class: synthetic pieces/junctions (fixture `tests/fixtures/beardifier.txt`, generated by
//! `tests/oracle/BeardifierOracle.java`), exact float bits for point and volume sampling plus the beard kernel.

use std::collections::BTreeMap;
use std::path::PathBuf;

use mc_core::bounding_box::BoundingBox;
use mc_core::pos::chunk_pos::ChunkPos;
use mc_worldgen::beardifier::{
    Beardifier, JigsawJunction, Rigid, StructurePieceInfo, StructurePieceKind, StructureStartInfo,
    TerrainAdjustment,
};
use mc_worldgen::densityfunction::{DensityBuffer, DensitySampler, DensityVolume, SamplerContext};

const ADJUSTMENTS: [TerrainAdjustment; 5] = [
    TerrainAdjustment::None,
    TerrainAdjustment::Bury,
    TerrainAdjustment::BeardThin,
    TerrainAdjustment::BeardBox,
    TerrainAdjustment::Encapsulate,
];

fn fnv(mut h: u64, word: u32) -> u64 {
    for i in 0..4 {
        h ^= u64::from((word >> (8 * i)) & 0xFF);
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

#[derive(Default)]
struct Case {
    rigids: Vec<Rigid>,
    junctions: Vec<JigsawJunction>,
    affected: Option<BoundingBox>,
    samples: Vec<([i32; 3], u32)>,
    volumes: Vec<([i32; 9], u64)>,
}

fn ints<const N: usize>(parts: &[&str]) -> [i32; N] {
    std::array::from_fn(|i| parts[i].parse().unwrap())
}

#[test]
fn beardifier_matches_vanilla() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/beardifier.txt");
    let text = std::fs::read_to_string(path).unwrap();
    let mut cases: BTreeMap<i32, Case> = BTreeMap::new();
    let mut kernel_hash = None;
    for line in text.lines() {
        let parts: Vec<&str> = line.split(' ').collect();
        match parts[0] {
            "KERNEL" => kernel_hash = Some(u64::from_str_radix(parts[1], 16).unwrap()),
            tag => {
                let case = cases.entry(parts[1].parse().unwrap()).or_default();
                match tag {
                    "R" => {
                        let v: [i32; 8] = ints(&parts[2..]);
                        case.rigids.push(Rigid {
                            bounding_box: BoundingBox::new(v[1], v[2], v[3], v[4], v[5], v[6]),
                            terrain_adjustment: ADJUSTMENTS[v[0] as usize],
                            ground_level_delta: v[7],
                        });
                    }
                    "J" => {
                        let v: [i32; 3] = ints(&parts[2..]);
                        case.junctions.push(JigsawJunction {
                            source_x: v[0],
                            source_ground_y: v[1],
                            source_z: v[2],
                        });
                    }
                    "W" => {
                        let v: [i32; 6] = ints(&parts[2..]);
                        case.affected = Some(BoundingBox::new(v[0], v[1], v[2], v[3], v[4], v[5]));
                    }
                    "S" => {
                        let v: [i32; 3] = ints(&parts[2..]);
                        case.samples
                            .push((v, u32::from_str_radix(parts[5], 16).unwrap()));
                    }
                    "V" => {
                        let v: [i32; 9] = ints(&parts[2..]);
                        case.volumes
                            .push((v, u64::from_str_radix(parts[11], 16).unwrap()));
                    }
                    other => panic!("unknown tag {other}"),
                }
            }
        }
    }
    assert_eq!(cases.len(), 40);

    let ctx = SamplerContext::empty_uncached();
    let mut checked = 0;
    for (id, case) in &cases {
        let beardifier =
            Beardifier::new(case.rigids.clone(), case.junctions.clone(), case.affected);
        for (pos, bits) in &case.samples {
            let value = beardifier.sample_value(&ctx, pos[0], pos[1], pos[2]);
            assert_eq!(
                value.to_bits(),
                *bits,
                "case {id} sample at {pos:?}: {value}"
            );
            checked += 1;
        }
        for (v, hash) in &case.volumes {
            let volume = DensityVolume::new(v[0], v[1], v[2], v[3], v[4], v[5], v[6], v[7], v[8]);
            let mut buffer = DensityBuffer::create_unpooled(volume.size());
            beardifier.sample_volume(&ctx, &mut buffer, &volume);
            let h = buffer
                .as_slice()
                .iter()
                .fold(0xcbf29ce484222325u64, |h, f| fnv(h, f.to_bits()));
            assert_eq!(h, *hash, "case {id} volume {v:?}");
            checked += 1;
        }
    }
    assert!(checked > 2000);

    let kernel = Beardifier::new(
        Vec::new(),
        vec![JigsawJunction {
            source_x: 0,
            source_ground_y: 0,
            source_z: 0,
        }],
        Some(BoundingBox::new(-30, -30, -30, 30, 30, 30)),
    );
    let mut h = 0xcbf29ce484222325u64;
    for z in -14..=14 {
        for x in -14..=14 {
            for y in -14..=14 {
                h = fnv(h, kernel.sample_value(&ctx, x, y, z).to_bits());
            }
        }
    }
    assert_eq!(Some(h), kernel_hash, "beard kernel");
}

/// `forStructuresInChunk` keeps only close pieces/junctions and inflates the union by 24.
#[test]
fn for_structures_in_chunk_selection() {
    let near = BoundingBox::new(0, 60, 0, 10, 70, 10);
    let far = BoundingBox::new(500, 60, 500, 510, 70, 510);
    let starts = [
        StructureStartInfo {
            terrain_adaptation: TerrainAdjustment::BeardThin,
            pieces: vec![
                StructurePieceInfo {
                    bounding_box: near,
                    kind: StructurePieceKind::Plain,
                },
                StructurePieceInfo {
                    bounding_box: far,
                    kind: StructurePieceKind::Plain,
                },
                StructurePieceInfo {
                    bounding_box: BoundingBox::new(-5, 60, -5, 3, 70, 3),
                    kind: StructurePieceKind::PoolElement {
                        rigid: false,
                        ground_level_delta: 2,
                        junctions: vec![
                            JigsawJunction {
                                source_x: 5,
                                source_ground_y: 64,
                                source_z: 5,
                            },
                            JigsawJunction {
                                source_x: 400,
                                source_ground_y: 64,
                                source_z: 5,
                            },
                        ],
                    },
                },
            ],
        },
        StructureStartInfo {
            terrain_adaptation: TerrainAdjustment::None,
            pieces: vec![StructurePieceInfo {
                bounding_box: near,
                kind: StructurePieceKind::Plain,
            }],
        },
    ];
    let beardifier = Beardifier::for_structures_in_chunk(ChunkPos::new(0, 0), &starts);
    let affected = beardifier.affected_box().expect("pieces near the chunk");
    assert_eq!(
        *affected,
        BoundingBox::new(0, 60, 0, 10, 70, 10).inflated_by(24)
    );
    assert!(
        Beardifier::for_structures_in_chunk(ChunkPos::new(40, 40), &starts[1..])
            .affected_box()
            .is_none()
    );
}
